/* Listening progress deliberately uses its own key: existing book state is untouched. */
(()=>{'use strict';
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const KEY='nihongo-path-listening-v1',LEVELS=['N5','N4','N3','N2','N1','EXTRA'];
 let mountId=0,cleanup=()=>{};
 function readProgress(){try{const x=JSON.parse(localStorage.getItem(KEY)||'{}');return x&&typeof x==='object'&&!Array.isArray(x)?x:{}}catch{return {}}}
 function eligible(lesson,rights){return rights?.verified===true&&rights?.audioRedistribution===true&&rights?.transcriptRedistribution===true&&rights?.translations===true&&rights?.publicWebsite===true&&rights?.publicRepository===true&&(!rights?.advertisingEnabled||rights?.commercialUse===true)&&lesson.verification?.decodable===true&&lesson.verification?.sourceAssociation===true&&lesson.verification?.semanticAudioMatch===true&&lesson.verification?.translationReviewed===true&&lesson.verification?.quizReviewed===true}
 function rubyHTML(lines){return lines.map(line=>line.map(p=>typeof p==='string'?escape(p):`<ruby>${escape(p.text)}<rt>${escape(p.reading)}</rt></ruby>`).join('')).join('\n')}
 async function mount(root,{lang='bn'}={}){
  cleanup();const run=++mountId,bn=lang==='bn',t=(en,be)=>bn?be:en;const params=new URLSearchParams(location.search),level=LEVELS.includes(params.get('level'))?params.get('level'):'N5';let rows=[],position=0,audio=null,saved=readProgress(),keyHandler=null;
  const head=()=>`<span class="eyebrow">02 / LISTENING BOOKS</span><h1>${t('Listen. Find the words.','শুনুন। শব্দগুলো চিনুন।')}</h1><nav class="listening-levels" aria-label="Listening levels">${LEVELS.map(n=>`<a class="chip ${n===level?'active':''}" href="listening.html?level=${n}" ${n===level?'aria-current="page"':''}>${n==='EXTRA'?t('Extra','অতিরিক্ত'):n}${n==='N1'?t(' · LOCK',' · লক'):''}</a>`).join('')}</nav>`;
  const stop=()=>{if(audio){if(audio.dataset.lesson){saved[audio.dataset.lesson]={...saved[audio.dataset.lesson],time:audio.currentTime};persist()}audio.onpause=null;audio.ontimeupdate=null;audio.onerror=null;audio.pause();audio.removeAttribute('src');audio.load();audio=null}};
  cleanup=()=>{stop();if(keyHandler)document.removeEventListener('keydown',keyHandler)};
  const empty=(title,message)=>{stop();root.innerHTML=head()+`<section class="paper-card listening-empty"><span class="eyebrow">${escape(level)} / ${t('LISTENING','লিসেনিং')}</span><h2>${title}</h2><p>${message}</p><a class="quiet-link" href="index.html">${t('Back to books','বইয়ে ফিরে যান')} ↗</a></section>`};
  if(level==='N1'){empty(t('N1 is locked','N1 লক করা আছে'),t('This section is currently unavailable.','এই বিভাগটি আপাতত বন্ধ আছে।'));return}
  if(level!=='N5'){empty(t('Lessons are not available yet','পাঠ এখনো যুক্ত করা হয়নি'),t('This is a separate listening section. No completed lesson collection is claimed.','এটি আলাদা লিসেনিং বিভাগ। এখানে এখনো সম্পূর্ণ বা যাচাইকৃত পাঠ যুক্ত করা হয়নি।'));return}
  root.innerHTML=head()+`<p role="status">${t('Opening the listening book…','লিসেনিং বই খুলছে…')}</p>`;
  let data;try{const response=await fetch('data/listening-n5.json?v=1');if(!response.ok)throw Error();data=await response.json();if(!Array.isArray(data.lessons))throw Error()}catch{if(run!==mountId)return;empty(t('Unable to open this book','বই খোলা যায়নি'),t('Please check your connection and reload this page.','ইন্টারনেট সংযোগ দেখে পৃষ্ঠাটি আবার খুলুন।'));return}
  if(run!==mountId)return;
  rows=data.lessons.filter(x=>x.level===level&&eligible(x,data.rights));
  if(!rows.length){empty(t('N5 listening is being prepared','N5 লিসেনিং প্রস্তুত করা হচ্ছে'),t('Source collection and review are in progress. Lessons will appear after permission and content checks are complete.','উৎস সংগ্রহ ও যাচাই চলছে। প্রকাশের অনুমতি এবং পাঠ যাচাই শেষ হলে এখানে পাঠ দেখা যাবে।'));return}
  const requested=rows.findIndex(x=>x.id===params.get('lesson'));position=requested>=0?requested:Math.max(0,rows.findIndex(x=>!saved[x.id]?.complete));
  function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));return true}catch{return false}}
  function update(delta){const e=rows[position];saved[e.id]={...saved[e.id],...delta};return persist()}
  function render(){stop();const e=rows[position],progress=saved[e.id]||{};history.replaceState(null,'',`listening.html?level=${level}&lesson=${encodeURIComponent(e.id)}`);root.innerHTML=head()+`<div class="listen-tools"><label for="listenPage">${t('Lesson','পাঠ')}</label><select id="listenPage" class="listen-page-select">${rows.map((x,i)=>`<option value="${i}" ${i===position?'selected':''}>${x.series} / ${x.number} · ${escape(x.title)}</option>`).join('')}</select><span class="listen-bookmark">${rows.filter(x=>saved[x.id]?.complete).length} / ${rows.length} ${t('completed','সম্পন্ন')}</span></div><article class="listening-book"><span class="eyebrow">N5 / LEVEL ${escape(e.series)} / ${escape(e.number)}</span><h2 class="listen-page-title" lang="ja">${escape(e.title)}</h2><audio id="lessonAudio" controls preload="metadata" aria-label="${t('Lesson audio','পাঠের অডিও')}" src="${escape(e.audio)}"></audio><p id="audioStatus" role="status"></p><div class="listen-tools"><button class="chip" id="listenReplay">↺ ${t('Replay','আবার শুনুন')}</button><label for="listenSpeed">${t('Speed','গতি')}</label><select id="listenSpeed"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option></select></div><div class="listen-spread"><section><h3>${t('Japanese transcript','জাপানি স্ক্রিপ্ট')}</h3><details><summary>${t('Show / hide transcript','স্ক্রিপ্ট দেখুন / লুকান')}</summary><div class="listen-text" lang="ja">${e.ruby?rubyHTML(e.ruby):escape(e.transcript)}</div></details><details class="listen-translations"><summary>${t('Bengali translation','বাংলা অনুবাদ')}</summary><p class="listen-text" lang="bn">${escape(e.translations.bn)}</p></details><details class="listen-translations"><summary>English translation</summary><p class="listen-text" lang="en">${escape(e.translations.en)}</p></details></section><section><h3>${t('Listening questions','শোনার অনুশীলন')}</h3><p class="listen-text" lang="ja">${escape(e.exercise)}</p><form id="listenQuiz" class="listen-quiz">${e.quiz.map((q,i)=>`<fieldset><legend>${escape(q.prompt[lang]||q.prompt.en)}</legend>${q.choices.map((c,j)=>`<label><input type="radio" name="q${i}" value="${j}" ${progress.answers?.[i]===j?'checked':''} required>${escape(c[lang]||c.en)}</label>`).join('')}</fieldset>`).join('')}<button class="primary" type="submit">${t('Check answers','উত্তর যাচাই করুন')}</button></form><p id="quizResult" role="status"></p><details><summary>${t('Show / hide answers','উত্তর দেখুন / লুকান')}</summary><div class="listen-answers">${e.sourceAnswers?.length?escape(e.sourceAnswers.map((answer,i)=>`${i+1}. ${answer}`).join("\n"))+"<hr>":""}${e.quiz.map((q,i)=>`${i+1}. ${escape(q.choices[q.answer][lang]||q.choices[q.answer].en)}\n${escape(q.explanation?.[lang]||q.explanation?.en||'')}`).join('\n\n')}</div></details></section></div><div class="listen-tools"><label><input type="checkbox" id="listenComplete" ${progress.complete?'checked':''}> ${t('Mark lesson complete','পাঠ সম্পন্ন চিহ্নিত করুন')}</label><span id="listenSaved" role="status" class="listen-saved"></span></div><p class="listen-source">${t('Source','উৎস')}: <a href="${escape(e.source)}" target="_blank" rel="noopener noreferrer">MLC Japanese</a> · ${escape(data.rights.attribution||'')}</p></article><nav class="listen-pages" aria-label="Listening book page navigation"><button id="listenPrev" class="chip" ${position===0?'disabled':''}>← ${t('Previous','আগের পাতা')}</button><span>${position+1} / ${rows.length}</span><button id="listenNext" class="chip" ${position===rows.length-1?'disabled':''}>${t('Next','পরের পাতা')} →</button></nav><p class="listen-saved">${t('Listening progress is saved on this device, separately from your book progress.','লিসেনিংয়ের অগ্রগতি বইয়ের অগ্রগতি থেকে আলাদাভাবে এই ডিভাইসে সংরক্ষিত থাকে।')}</p>`;
   const $=s=>root.querySelector(s);audio=$('#lessonAudio');audio.dataset.lesson=e.id;audio.onerror=()=>{$('#audioStatus').textContent=t('Audio could not be loaded. Check your connection or try another lesson.','অডিও লোড হয়নি। সংযোগ পরীক্ষা করুন অথবা অন্য পাঠ খুলুন।');$('#audioStatus').className='listen-error'};
   audio.addEventListener('loadedmetadata',()=>{if(Number.isFinite(progress.time)&&progress.time>0&&progress.time<audio.duration)audio.currentTime=progress.time},{once:true});let last=0;audio.ontimeupdate=()=>{if(Math.abs(audio.currentTime-last)>=5){last=audio.currentTime;update({time:last})}};audio.onpause=()=>update({time:audio?.currentTime||0});
   $('#listenReplay').onclick=async()=>{audio.currentTime=0;try{await audio.play()}catch{$('#audioStatus').textContent=t('Press play on the audio player to start.','শুরু করতে অডিও প্লেয়ারের Play চাপুন।')}};
   $('#listenSpeed').onchange=e=>audio.playbackRate=Number(e.target.value);
   $('#listenPage').onchange=e=>{position=Number(e.target.value);render()};$('#listenPrev').onclick=()=>turn(-1);$('#listenNext').onclick=()=>turn(1);
   $('#listenComplete').onchange=e=>{const ok=update({complete:e.target.checked});$('#listenSaved').textContent=ok?t('Saved','সংরক্ষিত'):t('Could not save progress. Browser storage may be full.','অগ্রগতি সংরক্ষণ হয়নি। ব্রাউজারের জায়গা পূর্ণ থাকতে পারে।')};
   $('#listenQuiz').onsubmit=event=>{event.preventDefault();const answers=e.quiz.map((q,i)=>Number(new FormData(event.target).get('q'+i))),score=answers.filter((x,i)=>x===e.quiz[i].answer).length;update({answers,score});$('#quizResult').textContent=`${score} / ${e.quiz.length} · ${t('correct','সঠিক')}`};
  }
  function turn(delta){const next=Math.max(0,Math.min(rows.length-1,position+delta));if(next!==position){position=next;render()}}
  keyHandler=event=>{if(event.altKey||event.ctrlKey||event.metaKey||event.shiftKey||event.target.closest('input,select,textarea,audio,button,summary'))return;if(event.key==='ArrowRight'){event.preventDefault();turn(1)}if(event.key==='ArrowLeft'){event.preventDefault();turn(-1)}};document.addEventListener('keydown',keyHandler);render();
 }
 window.NPListening={mount,eligible,rubyHTML,readProgress};
})();
